import{_ as a,o as s,c as i,ag as t}from"./chunks/framework.DFlFRONG.js";const g=JSON.parse('{"title":"TeamOne Proxy Server Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"proxy-server/configuration.md","filePath":"proxy-server/configuration.md"}'),n={name:"proxy-server/configuration.md"};function o(l,e,p,r,h,d){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="teamone-proxy-server-configuration" tabindex="-1">TeamOne Proxy Server Configuration <a class="header-anchor" href="#teamone-proxy-server-configuration" aria-label="Permalink to &quot;TeamOne Proxy Server Configuration&quot;">​</a></h1><p>This page describes the common TeamOne Proxy Server configuration used by both installation models:</p><ul><li>SSL managed by a load balancer</li><li>SSL managed directly by the TeamOne Proxy Server</li></ul><p>The main configuration file is:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>teamone-server-distr/config/.env</span></span></code></pre></div><p>For questions or assistance, contact <strong><a href="mailto:teamone@succeedium.com" target="_blank" rel="noreferrer">teamone@succeedium.com</a></strong>.</p><h2 id="oauth-sso-allowed-hosts" tabindex="-1">OAuth / SSO Allowed Hosts <a class="header-anchor" href="#oauth-sso-allowed-hosts" aria-label="Permalink to &quot;OAuth / SSO Allowed Hosts&quot;">​</a></h2><p><code>PROXY_OAUTH_ALLOWED_HOST_PATTERN</code> controls which hosts can be used by the TeamOne OAuth / SSO endpoints, including:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/oauth/login/</span></span>
<span class="line"><span>/oauth/token/</span></span>
<span class="line"><span>/oauth/logout/</span></span></code></pre></div><p>For IBM Planning Analytics Local, SSO is commonly handled through IBM Cognos Analytics.</p><p>The allowed host should normally match the Cognos Gateway hostname configured in the <code>ClientCAMURI</code> parameter in <code>tm1s.cfg</code>.</p><p>Example:</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ClientCAMURI</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=https://cognos.company.com/ibmcognos/bi/v1/disp</span></span></code></pre></div><p>Configure:</p><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">PROXY_OAUTH_ALLOWED_HOST_PATTERN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=cognos.company.com</span></span></code></pre></div><p>Use the hostname only, not the full URL or path.</p><p>If there are multiple Cognos Gateway hosts, separate them with commas:</p><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">PROXY_OAUTH_ALLOWED_HOST_PATTERN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=cognos-prod.company.com,cognos-qa.company.com</span></span></code></pre></div><p>Wildcard patterns are also supported:</p><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">PROXY_OAUTH_ALLOWED_HOST_PATTERN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=*.company.com</span></span></code></pre></div><p>If Cognos SSO is not used, configure a non-matching placeholder value:</p><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">PROXY_OAUTH_ALLOWED_HOST_PATTERN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=disabled.local</span></span></code></pre></div><h2 id="ibm-planning-analytics-tm1-allowed-hosts" tabindex="-1">IBM Planning Analytics / TM1 Allowed Hosts <a class="header-anchor" href="#ibm-planning-analytics-tm1-allowed-hosts" aria-label="Permalink to &quot;IBM Planning Analytics / TM1 Allowed Hosts&quot;">​</a></h2><p><code>PROXY_ALLOWED_HOST_PATTERN</code> controls which IBM Planning Analytics / TM1 hosts can be accessed through the TeamOne Proxy Server.</p><p>Use specific TM1 hostnames where practical:</p><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">PROXY_ALLOWED_HOST_PATTERN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=tm1-prod.internal.company.com,tm1-dev.internal.company.com</span></span></code></pre></div><p>A wildcard can also be used for a trusted internal domain:</p><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">PROXY_ALLOWED_HOST_PATTERN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=*.internal.company.com</span></span></code></pre></div><p>Avoid overly broad patterns such as:</p><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">*</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">*.com</span></span></code></pre></div><p>in production environments.</p><h2 id="applying-configuration-changes" tabindex="-1">Applying Configuration Changes <a class="header-anchor" href="#applying-configuration-changes" aria-label="Permalink to &quot;Applying Configuration Changes&quot;">​</a></h2><p>After updating <code>teamone-server-distr/config/.env</code>, recreate the TeamOne Proxy Server containers so the new environment settings are applied:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker-compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> teamone-server-distr/docker-compose.yml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force-recreate</span></span></code></pre></div><h2 id="verify-the-teamone-proxy-server" tabindex="-1">Verify the TeamOne Proxy Server <a class="header-anchor" href="#verify-the-teamone-proxy-server" aria-label="Permalink to &quot;Verify the TeamOne Proxy Server&quot;">​</a></h2><p>Open the configured TeamOne Proxy Server URL in a browser:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://&lt;teamone-proxy-fqdn&gt;</span></span></code></pre></div><p>Confirm that it displays:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TeamOne is up!</span></span></code></pre></div><h2 id="related-documentation" tabindex="-1">Related Documentation <a class="header-anchor" href="#related-documentation" aria-label="Permalink to &quot;Related Documentation&quot;">​</a></h2><ul><li><a href="./index.html">About TeamOne Proxy Server</a></li><li><a href="./installation-load-balancer-ssl.html">Installation Guide – SSL Managed by Load Balancer</a></li><li><a href="./installation-direct-ssl.html">Installation Guide – SSL Managed by TeamOne Proxy Server</a></li><li><a href="./upgrade-load-balancer-ssl.html">Upgrade Guide – SSL Managed by Load Balancer</a></li><li><a href="./upgrade-direct-ssl.html">Upgrade Guide – SSL Managed by TeamOne Proxy Server</a></li><li><a href="./troubleshooting.html">Troubleshooting</a></li></ul>`,41)])])}const u=a(n,[["render",o]]);export{g as __pageData,u as default};
